                <el-icon :size="18"><component :is="tab.icon" /></el-icon>
                <span class="nav-label">{{ tab.label }}</span>
              </div>
              <el-badge 
                v-if="tab.unread > 0" 
                :value="tab.unread" 
                :max="99" 
