            <span class="message-count" v-if="filteredMessages.length > 0">{{ filteredMessages.length }} 条</span>
          </div>
          
          <div class="message-list" v-loading="loading">
            <template v-if="filteredMessages.length > 0">
              <div 
                v-for="msg in filteredMessages" 
                :key="msg.id" 
                class="message-item"
                :class="{ unread: !msg.is_read }"
                @click="viewMessage(msg)"
              >
                <div class="msg-avatar-wrapper">
                  <el-avatar :size="44" :class="msg.sender_name === '系统管理员' ? 'system-avatar' : 'user-avatar'">
                    {{ msg.sender_name?.charAt(0) }}
                  </el-avatar>
                  <div class="unread-dot" v-if="!msg.is_read"></div>
                </div>
                <div class="msg-content">
