<script setup>
import { ref, reactive, onMounted, computed } from 'vue'
import { 
  ChatDotRound, Plus, Bell, Message as MessageIcon, 
  User, ArrowRight, Clock, ChatLineSquare, Check
} from '@element-plus/icons-vue'
import api from '@/api'
import dayjs from 'dayjs'
import { ElMessage } from 'element-plus'

const activeTab = ref('all')
const messages = ref([])
const users = ref([])
const currentUser = ref(null)
const loading = ref(false)
const sending = ref(false)
const viewDialogVisible = ref(false)
const newMessageDialog = ref(false)
const selectedMessage = ref(null)

const tabs = computed(() => [
  { name: 'notifications', label: '系统通知', icon: Bell, unread: unreadCount('notifications') },
  { name: 'private', label: '我的私信', icon: MessageIcon, unread: unreadCount('private') },
  { name: 'all', label: '全部消息', icon: ChatDotRound, unread: unreadCount('all') }
])

const unreadTotal = computed(() => unreadCount('all'))

const newMessageForm = reactive({
  receiver: '',
  title: '',
  content: ''
})

/** 审批/申请类消息（发件人常为学生或老师，不是「系统管理员」） */
const isWorkflowNotice = (m) => {
  const t = `${m.title || ''} ${m.content || ''}`
  if (m.sender_name === '系统管理员') return true
  return /审批|申请|通过|驳回|新的/.test(t)
}

const unreadCount = (type) => {
  return messages.value.filter(m => {
    if (m.is_read) return false
    if (type === 'all') return true
    if (type === 'notifications') return isWorkflowNotice(m)
    return !isWorkflowNotice(m)
  }).length
}

const currentTabLabel = computed(() => {
  return tabs.value.find(t => t.name === activeTab.value)?.label || '消息列表'
})

const filteredMessages = computed(() => {
  return messages.value.filter(m => {
    if (activeTab.value === 'all') return true
    if (activeTab.value === 'notifications') return isWorkflowNotice(m)
    return !isWorkflowNotice(m)
  })
})

const availableUsers = computed(() => {
  return users.value.filter(u => u.id !== currentUser.value?.id)
})

const allReadDisabled = computed(() => {
  return !filteredMessages.value.some(m => !m.is_read)
})

const fetchMessages = async () => {
  loading.value = true
  try {
    const userId = currentUser.value?.id
    const res = await api.getMessages(userId)
    messages.value = res.data.results || res.data || []
  } catch (error) {
    ElMessage.error('获取消息失败')
  } finally {
    loading.value = false
  }
}

const fetchUsers = async () => {
  try {
    const res = await api.getProfiles()
    users.value = res.data.results || res.data || []
  } catch (error) {
    ElMessage.error('获取用户列表失败')
  }
}

const viewMessage = async (msg) => {
  selectedMessage.value = msg
  viewDialogVisible.value = true
  if (!msg.is_read) {
    try {
      const userId = currentUser.value?.id
      await api.updateMessage(msg.id, { message_id: msg.id })
      msg.is_read = true
      window.dispatchEvent(new Event('message-updated'))
    } catch (error) {
      console.error('标记已读失败')
    }
  }
}

const markAllAsRead = async () => {
  const unread = filteredMessages.value.filter(m => !m.is_read)
  if (unread.length === 0) return
  try {
    loading.value = true
    await api.markAllMessagesAsRead(unread.map(m => m.id))
    // 立即更新本地状态，提升响应感
    unread.forEach(m => m.is_read = true)
    ElMessage.success('当前分类下未读消息已全部标记为已读')
    window.dispatchEvent(new Event('message-updated'))
    // 重新获取最新列表以同步
    await fetchMessages()
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '操作失败'))
  } finally {
    loading.value = false
  }
}

const sendMessage = async () => {
  if (!newMessageForm.receiver || !newMessageForm.title || !newMessageForm.content) {
    ElMessage.warning('请填写完整的消息信息')
    return
  }
  
  sending.value = true
  try {
    const receiverId = Number(newMessageForm.receiver)
    if (!Number.isFinite(receiverId) || receiverId <= 0) {
      ElMessage.warning('请选择有效的收件人')
      return
    }
    await api.createMessage({
      receiver: receiverId,
      title: newMessageForm.title.trim(),
      content: newMessageForm.content.trim(),
    })
    ElMessage.success('私信发送成功')
    newMessageDialog.value = false
    Object.assign(newMessageForm, { receiver: '', title: '', content: '' })
    fetchMessages()
    window.dispatchEvent(new Event('message-updated'))
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '发送失败'))
  } finally {
    sending.value = false
  }
}

const replyMessage = () => {
  const senderId = selectedMessage.value.sender
  newMessageForm.receiver = senderId
  newMessageForm.title = `回复: ${selectedMessage.value.title}`
  newMessageForm.content = '\n\n------------------\n' + selectedMessage.value.content
  viewDialogVisible.value = false
  newMessageDialog.value = true
}

const formatDate = (date) => dayjs(date).format('YYYY-MM-DD HH:mm')

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) {
    currentUser.value = JSON.parse(userStr)
  }
  fetchMessages()
  fetchUsers()
})
</script>

